static void format_uptime(char*out,size_t z){FILE*f=fopen("/proc/uptime","r");double s=0;if(f){fscanf(f,"%lf",&s);fclose(f);}long q=(long)s;int d=q/86400;q%=86400;int h=q/3600;q%=3600;int m=q/60;q%=60;if(d)snprintf(out,z,"%dd %02d:%02d:%02ld",d,h,m,q);else snprintf(out,z,"%02d:%02d:%02ld",h,m,q);}
