static void persist_playback_config(void){if(save_playback_config()!=0)fprintf(stderr,"Einstellungen: config.ini konnte nicht gespeichert werden.\n");}static void toggle_repeat_book(void){repeat_book=!repeat_book;persist_playback_config();}static void change_shutdown_tracks(int d){shutdown_after_tracks+=d;if(shutdown_after_tracks<0)shutdown_after_tracks=0;if(shutdown_after_tracks>999)shutdown_after_tracks=999;persist_playback_config();}static void toggle_shutdown_end(void){shutdown_at_book_end=!shutdown_at_book_end;persist_playback_config();}static void change_volume(int d){volume+=d;if(volume<0)volume=0;if(volume>MIX_MAX_VOLUME)volume=MIX_MAX_VOLUME;Mix_VolumeMusic(volume);save_state();}static void change_output(int d){output_volume_change(d,NULL);}static void change_bt(int d){char s[512];int v;if(bluetooth_audio_sink_get(s,sizeof(s),&v)!=0||!s[0])return;v+=d;if(v<0)v=0;if(v>100)v=100;bluetooth_audio_sink_set_volume(s,v);}static void change_brightness(int d){int p=get_brightness_percent();if(p<0)return;p+=d;if(p<10)p=10;if(p>100)p=100;set_brightness_percent(p);}static void change_display_timeout(int d){int x=0;for(int i=0;i<DISPLAY_TIMEOUT_COUNT;i++)if(DISPLAY_TIMEOUTS[i]==display_timeout_seconds)x=i;x+=d;if(x<0)x=DISPLAY_TIMEOUT_COUNT-1;if(x>=DISPLAY_TIMEOUT_COUNT)x=0;display_timeout_seconds=DISPLAY_TIMEOUTS[x];save_state();}static void edit_sleep_timer(ScreenContext*c,int d){if(sleep_timer_edit_minutes<0)sleep_timer_edit_minutes=*c->sleep_timer_minutes;sleep_timer_edit_minutes+=d;if(sleep_timer_edit_minutes<SLEEP_MIN_MINUTES)sleep_timer_edit_minutes=SLEEP_MIN_MINUTES;if(sleep_timer_edit_minutes>SLEEP_MAX_MINUTES)sleep_timer_edit_minutes=SLEEP_MAX_MINUTES;}static void confirm_sleep_timer(ScreenContext*c){int m=sleep_timer_edit_minutes>=0?sleep_timer_edit_minutes:*c->sleep_timer_minutes;*c->sleep_timer_minutes=m;if(m==0){*c->sleep_timer_active=0;*c->sleep_timer_end_ticks=0;}else{*c->sleep_timer_active=1;*c->sleep_timer_end_ticks=SDL_GetTicks()+(Uint32)(m*60000);}sleep_timer_edit_minutes=-1;}static void change_idle_timer(int d){idle_timer_minutes+=d;if(idle_timer_minutes<0)idle_timer_minutes=0;if(idle_timer_minutes>IDLE_TIMER_MAX_MINUTES)idle_timer_minutes=IDLE_TIMER_MAX_MINUTES;save_state();}
